"""ID-side avatar stock — every identity has a valid avatar (operator 2026-08).

Mirrors hive's resolution (hive/hive_project/avatars.py) so a user's default
avatar is byte-identical across Hive, ID and Home:

  ``https://shizuha.com/avatars/stock/<sha256(username)%N:03d>.png``

A user who selects/edits their own avatar stores the chosen ``profile_picture``
on UserProfile, which then takes precedence everywhere (avatar == profile image).
"""
import hashlib

from django.conf import settings

# Must match the size of home/frontend/public/avatars/stock/*.png (generated by
# home/scripts/generate_avatars.py) and hive's AVATAR_STOCK_SIZE.
STOCK_SIZE = 160

DEFAULT_STOCK_BASE_URL = 'https://shizuha.com/avatars'


def stock_seed(key):
    """Deterministic int seed for a username/email — identical slices to hive's
    avatar_seed so a user's default avatar is byte-identical across services."""
    digest = hashlib.sha256(str(key or '').strip().lower().encode('utf-8')).digest()
    return int.from_bytes(digest[:4], 'big')


def stock_avatar_url(key):
    """The default (deterministic) stock avatar URL for an identity key."""
    base = str(getattr(settings, 'AVATAR_BASE_URL', DEFAULT_STOCK_BASE_URL) or '').rstrip('/')
    if not base or not key:
        return None
    idx = stock_seed(key) % STOCK_SIZE
    return f'{base}/stock/{idx:03d}.png'


def assign_default_avatar(profile, username):
    """Give ``profile`` a valid stock avatar when it has none.

    The stored ``profile_picture`` is the user's profile image; a custom pick or
    upload overrides the stock default. Only writes (and saves) when both the
    profile exists and picture is unset.
    """
    if profile is None:
        return None
    if profile.profile_picture:
        return profile.profile_picture
    url = stock_avatar_url(username)
    if not url:
        return None
    profile.profile_picture = url
    profile.save(update_fields=['profile_picture'])
    return url
